    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]

    def process_line(coords):
        marks = [i for i, (r, c) in enumerate(coords) if grid[r][c] == fg]
        n = len(coords)
        if not marks:
            return

        # Fill enclosed gaps on busy lines, and gaps that start/end at an edge.
        for a, b in zip(marks, marks[1:]):
            if b == a + 1:
                continue
            if len(marks) >= 3 or a == 0 or b == n - 1:
                for i in range(a + 1, b):
                    r, c = coords[i]
                    out[r][c] = 2

        # A long horizontal bar that begins away from the border extends to it.
        if len(coords) == w and marks[0] > 0:
            run = 0
            i = marks[0]
            while i + run < w and grid[coords[i + run][0]][coords[i + run][1]] == fg:
                run += 1
            if run >= 3:
                for i in range(marks[0]):
                    r, c = coords[i]
                    out[r][c] = 2

    for r in range(h):
        process_line([(r, c) for c in range(w)])
    for c in range(w):
        process_line([(r, c) for r in range(h)])

    return out
